export function timeDifference(givenTime) {
  const given = new Date(givenTime)
  const milliseconds = new Date().getTime() - given.getTime()
  const numberEnding = (number) => (number > 1 ? 's' : '')
  const number = (num) => (num > 9 ? `${num}` : `0${num}`)
  const getTime = () => {
    let temp = Math.floor(milliseconds / 1000)
    const years = Math.floor(temp / 31536000)
    if (years) {
      const month = number(given.getUTCMonth() + 1)
      const day = number(given.getUTCDate())
      const year = given.getUTCFullYear() % 100
      return `${day}-${month}-${year}`
    }
    const days = Math.floor((temp %= 31536000) / 86400)
    if (days) {
      if (days < 28) {
        return `${days} day${numberEnding(days)}`
      }
      const months = [
        'Jan',
        'Feb',
        'Mar',
        'Apr',
        'May',
        'Jun',
        'Jul',
        'Aug',
        'Sep',
        'Oct',
        'Nov',
        'Dec',
      ]
      const month = months[givenTime.getUTCMonth()]
      const day = number(givenTime.getUTCDate())
      return `${day} ${month}`
    }
    const hours = Math.floor((temp %= 86400) / 3600)
    if (hours) {
      return `${hours} hour${numberEnding(hours)} ago`
    }
    const minutes = Math.floor((temp %= 3600) / 60)
    if (minutes) {
      return `${minutes} minute${numberEnding(minutes)} ago`
    }
    return 'a few seconds ago'
  }
  return getTime()
}
export function envChecker(val) {
  switch (val) {
    case 'testing':
      return val.toUpperCase()
    case 'staging':
      return val.toUpperCase()
    default:
      return ''
  }
}

export const validatorCheck = (val1, val2, operator) => {
  const a = parseInt(val1, 10)
  const b = parseInt(val2, 10)
  switch (operator) {
    case 'eq':
      return a === b
    case 'gte':
      return a >= b
    case 'gt':
      return a > b
    case 'lt':
      return a < b
    case 'lte':
      return a <= b
    default:
      return false
  }
}

export function millisecondToHMS(ms) {
  // 1- Convert to seconds:
  let seconds = ms / 1000
  seconds %= 3600 // seconds remaining after extracting hours
  // 2- Extract minutes:
  const minutes = parseInt(seconds / 60, 10) // 60 seconds in 1 minute
  // 3- Keep only seconds not extracted to minutes:
  seconds %= 60
  return `0${minutes}:${seconds > 9 ? '' : 0}${seconds}`
}

