export const getAssets = () => {
  const { hostname } = window.location

  // Check for MRT domains first
  if (hostname.startsWith('mrt')) {
    return mrtAssets
  }

  if (hostname.includes('mkp')) return mkpAssets
  if (hostname.includes('ferizy')) return asdpAssets
  if (hostname.includes('ppibroker')) return ppBrokerAssets
  if (hostname.includes('vnpt-msig')) return vinaphoneAssets
  return pasarpolisAssets
}
