const verifyBankAccount = async ({ payload }) => {
  const uri = url.verifyBankAccount()
  return axios
    .post(`${uri}`, { payload }, { headers: getHeader() })
    .catch(error => {
      if (error.response) {
        throw error.response
      } else if (error.request) {
        throw error.request
      } else {
        throw error.message
      }
    })
    .then(response => {
      return response
    })
}

