const fileUploadUsingSignedUrl = async ({ signedUrlData, file }) => {
  try {
    return await axios.put(signedUrlData.signed_url,
      file,
      { headers: { 'Content-Type': file.type, 'Host': 'storage.googleapis.com' } }
    )
  } catch (error) {
    return error.message
  }
}

